@Entry
@Component
class FoodCategoryListPage {
    let foodItems = initializeOnStartup()

    @State
    var showList: Bool = false

    @State
    var selectedCategoryLabel: String = "All"

    func openFoodDetail(foodItem: FoodData): Unit {
        getUIContext().getRouter().pushUrl(url: "FoodDetailPage", params: foodItem.id)
    }

    func build() {
        Column {
            this.buildHeader()
            this.buildCategoryBar()
            this.buildSummaryBar()
        }
    }
}

@Entry
@Component
class ThemeSettingsPage {
    var manager: Option<UserSettingsManager> = Option<UserSettingsManager>.None

    @State
    var currentTheme: String = "default"

    @State
    var notificationEnabled: Bool = true

    protected override func aboutToAppear(): Unit {
        this.attachManager()
        this.syncFromManager()
    }

    func build() {
        Scroll {
            Column {
                this.buildHeader()
                this.buildStatusCard()
                this.buildThemeSelector()
            }
        }
