@Entry
@Component
public class EntryView {
    @State
    var dynamicTime: DynamicTime = DynamicTime()
    @State
    var dynamicStyle: DynamicStyle = DynamicStyle()
    @State
    var dynamicBill: DynamicBill = DynamicBill()

    @Builder
    func mainBody() {
        Column {
            TopBar()
            MonthPickerRow(dynamicTime: dynamicTime, dynamicStyle: dynamicStyle, dynamicBill: dynamicBill)
            SummaryBar(dynamicBill: dynamicBill)
            DetailsList(dynamicBill: dynamicBill)
        }
    }

    public func build() {
        Stack {
            DatePickerComponent(dynamicStyle: dynamicStyle, dynamicTime: dynamicTime, update: update)
            mainBody()
        }
    }
}

@Entry
@Component
public class ModalWindowView {
    @State var isPresent: Bool = false

    @Builder
    func loginBuilder() {
        Column() {
            DefaultLogin(isPresentInLoginView: this.isPresent)
        }
    }

    func build() {
        Column() {
            Button("点击跳转到全屏登录页")
                .bindContentCover(this.isPresent, this.loginBuilder, ContentCoverOptions(modalTransition: ModalTransition.DEFAULT, onDisappear: {=> this.isPresent = false}))
                .onClick({ event => this.isPresent = true })
        }
    }
}

@Entry
@Component
public class CustomTabBarPage {
    @Provide var selectedIndex: Int64 = 0
    private let controller: TabsController = TabsController()

    func build() {
        Column() {
            Tabs(BarPosition.End, this.controller, Int32(this.selectedIndex)) {
                TabContent() {
                    Text("首页")
                }
            }
            .onChange({ index: Int32 => this.selectedIndex = Int64(index) })

            CustomTabBar(selectedIndex: this.selectedIndex)
        }
    }
}

@Component
class MarkdownHeadingComponent {
    var markdownConfiguration: MarkdownConfiguration
    var nodeViews: ArrayList<NodeView>

    @State
    var level: Int64 = 1

    @Prop
    var componentWidth: Float64

    @State
    var nodeViewList: ObservedArrayList<NodeView> = ObservedArrayList<NodeView>()

    func build() {
        Column() {
            headingTitleComponent()
            if ((level == 1 || level == 2) && markdownConfiguration.markdownTheme.headingBreakHeight > 0.0) {
                Divider()
            }
        }
    }
}

@Component
public class PhotoView {
    @State
    var model: PhotoViewModel = PhotoViewModel()

    @State
    var currentScale: Float64 = 0.0

    public func zoomTo(scale: Float64, durationMs: Int32): Unit {
        if (scale > model.getMaximumScale()) {
            currentScale = model.getMaximumScale()
        } else if (scale < model.getMinimumScale()) {
            currentScale = model.getMinimumScale()
        } else {
            currentScale = scale
        }
    }

    func build() {
        Flex(FlexParams(direction: FlexDirection.Column)) { }
            .gesture(GestureGroup(GestureMode.Exclusive, [TapGesture(count: 2, fingers: 1)]))
    }
}

@Component
public class SVGImageView {
    @State
    var model: SVGImageViewModel = SVGImageViewModel()
    private var settings: RenderingContextSettings = RenderingContextSettings(antialias: true)
    private let context2D: CanvasRenderingContext2D = CanvasRenderingContext2D(this.settings)

    @Builder
    func setSvgCanvas(b: Bool) {
        Canvas(this.context2D).width(100.percent).height(100.percent).onReady({ =>
            this.model.setContext2D(this.context2D)
            this.model.doRender(this.model.context, areaChanged: true)
        })
    }

    func build() {
        Column {
            setSvgCanvas(pxTovpRes())
        }
    }
}
